    content: `
<p>Вы присоединяетесь к звонку Zoom. Ваша музыка резко затихает. Вы не трогали никакой регулятор громкости — что-то сделало это за вас. Это <strong>автоприглушение (ducking)</strong>: автоматическое понижение фонового звука, когда активен звонок или важный источник.</p>

<p>Некоторым нравится. Другие ненавидят — особенно когда приглушение слишком агрессивное (музыка падает до нуля вместо комфортного фонового уровня) или когда оно срабатывает неожиданно.</p>

<p>Вот как отключить нежелательное приглушение на Mac и как заменить его тем, которое работает так, как вам нужно.</p>

<h2>Откуда берётся автоприглушение на Mac</h2>

<p>macOS сама по себе <strong>не имеет</strong> встроенной функции автоприглушения. Если ваша музыка становится тише во время звонков, это вызвано одним из следующих:</p>

<h3>1. Аудиообработка Zoom</h3>
<p>Zoom может снижать системный звук при активации. Проверьте Zoom → Настройки → Аудио и отключите «Автоматически регулировать громкость микрофона». Также попробуйте снизить шумоподавление с «Высокого» на «Низкое».</p>

<h3>2. Переключение кодека Bluetooth</h3>
<p>Когда приложение активирует микрофон Bluetooth-наушников, macOS переключается с AAC на кодек SCO. Это не совсем «приглушение» — это смена кодека, из-за которой всё звучит тише и хуже. Исправьте, используя отдельный микрофон.</p>

<h3>3. Стороннее приложение</h3>
<p>Некоторые аудиоприложения (например, Background Music) имеют функции автопаузы или автоприглушения. Некоторые медиаприложения снижают собственную громкость при обнаружении другого источника звука. Проверьте установленные аудиоутилиты.</p>

<h3>4. Обработка звука в приложениях связи</h3>
<p>Discord, Teams и другие приложения связи имеют собственную обработку, которая может влиять на воспринимаемую громкость других приложений. Проверьте аудионастройки каждого приложения на «автоматическую регулировку» и отключите.</p>

<h2>Как остановить нежелательное приглушение</h2>

<ol>
  <li><strong>Проверьте аудионастройки Zoom/Teams/Discord</strong> — отключите автоматическую регулировку громкости/микрофона</li>
  <li><strong>Используйте отдельный микрофон для звонков</strong> — предотвращает переключение кодека Bluetooth</li>
  <li><strong>Удалите аудиоутилиты</strong> — Background Music, Soundflower или любое приложение, которое может перехватывать аудио</li>
  <li><strong>Проверьте Универсальный доступ macOS</strong> — Системные настройки → Универсальный доступ → Аудио на предмет неожиданных настроек</li>
</ol>

<h2>Замените плохое приглушение хорошим</h2>

<p>Идея автоприглушения на самом деле отличная — автоматически понижать фоновый звук во время звонков, чтобы слышать чётко. Проблема в том, когда оно слишком агрессивное (музыка падает до нуля), не настраиваемое (нельзя выбрать, насколько понижать) или срабатывает не от того.</p>

<p><a href="https://apps.apple.com/app/sounddial/id6772792641">SoundDial</a> имеет встроенную функцию автоприглушения, которая даёт вам контроль:</p>

<ul>
  <li><strong>Настраиваемый уровень:</strong> выбирайте, насколько точно понижать фоновый звук во время звонков — от 10% (почти бесшумно) до 80% (едва снижено). По умолчанию 30%, что сохраняет музыку слышной, но не отвлекающей.</li>
  <li><strong>Умное определение:</strong> определяет звонки, отслеживая использование микрофона — тот же индикатор, что и оранжевая точка macOS. Работает с Zoom, Teams, FaceTime, Discord, Slack, Google Meet, Webex, Skype.</li>
  <li><strong>Идеальное восстановление:</strong> когда звонок заканчивается, каждое приложение возвращается точно на свою предыдущую громкость. Без перенастройки.</li>
  <li><strong>Удобное переключение:</strong> включайте или выключайте автоприглушение в настройках SoundDial. Когда не нужно — отключите. Когда нужно — включите обратно.</li>
</ul>

<a href="https://apps.apple.com/app/sounddial/id6772792641" target="_blank" rel="noopener" style="display:block"><img src="/apps/sounddial.png" alt="Настраиваемое автоприглушение SoundDial — контролируйте, насколько именно понижается фоновый звук во время звонков" style="max-width:100%;border-radius:12px;margin:24px 0;" /></a>

<p>Разница: вместо того чтобы какое-то приложение решало, что ваша музыка должна упасть до нуля при каждом звонке, вы решаете, что она должна быть на 25%. Вместо потери контроля вы его обретаете. И вместо попыток отключить скрытую функцию в трёх разных приложениях у вас один переключатель в одном месте.</p>

<p><a href="https://apps.apple.com/app/sounddial/id6772792641">Скачать SoundDial в Mac App Store</a> — €14,99 разовая покупка, без подписки, macOS 14.2+.</p>
`,
