    title: "Как заставить Mac запоминать громкость для каждого приложения",
    description:
      "Каждый раз при перезапуске Spotify или Zoom приходится заново настраивать громкость. Вот как заставить macOS автоматически запоминать уровень каждого приложения.",
    date: "2026-04-18",
