    date: "2026-05-30",
    readTime: "4 мин чтения",
    content: `
<p>Вы работаете. Spotify играет фоновую музыку. Она немного громковата — конкурирует с подкастом в другой вкладке или мешает сосредоточиться. Нажимаете клавишу убавления громкости. Spotify становится тише. Но и всё остальное тоже — звонок Zoom, звуки уведомлений, аудио браузера. Это не то, что вы хотели.</p>

<p>Это происходит потому, что у macOS один ползунок. Нажмите клавишу громкости — она регулирует <em>системную громкость</em>, пропорционально масштабируя каждое приложение. Нет встроенного способа сказать «убавить только Spotify».</p>

<h2>Обходной путь: внутренний регулятор Spotify</h2>

<p>У Spotify есть собственный ползунок громкости в правом нижнем углу приложения (или внизу плеера). Его можно понизить независимо от системной громкости. Если системная на 80%, а ползунок Spotify на 30%, Spotify будет воспроизводиться на фактических 24%, пока всё остальное остаётся на 80%.</p>

<p><strong>Проблема:</strong> Нужно переключиться в окно Spotify, найти ползунок, настроить его, затем вернуться к работе. А ползунок Spotify маленький, неточный и не показывает процент — только визуальная полоска. Если вы на совещании и нужно быстро убавить музыку, возиться с маленьким ползунком в другом приложении — не идеально.</p>

<h2>Настоящее исправление: попрограммное управление громкостью</h2>

<p><a href="https://apps.apple.com/app/sounddial/id6772792641">SoundDial</a> размещает ползунок громкости для каждого приложения в строке меню. Чтобы убавить Spotify, не затронув ничего другого:</p>

<ol>
  <li>Нажмите значок SoundDial в строке меню</li>
  <li>Найдите Spotify в списке</li>
  <li>Переместите ползунок вниз</li>
</ol>

<p>Готово. Spotify тише. Zoom не изменился. Уведомления не изменились. Всё остальное не изменилось. Вы не покидали текущее приложение — панель строки меню открывается прямо там, где вы находитесь.</p>

<a href="https://apps.apple.com/app/sounddial/id6772792641" target="_blank" rel="noopener" style="display:block"><img src="/apps/sounddial.png" alt="SoundDial понижает громкость Spotify независимо, сохраняя другие приложения на полной громкости на macOS" style="max-width:100%;border-radius:12px;margin:24px 0;" /></a>

<h2>Ещё лучше: сохранить как профиль</h2>

<p>Если вы регулярно хотите Spotify на более низком фоновом уровне во время работы, сохраните предпочтительную конфигурацию громкости как профиль. Создайте профиль «Работа» с Spotify на 25%, Zoom на 100% и Slack на 15%. В следующий раз, садясь работать, примените профиль одним кликом вместо настройки каждого приложения по отдельности.</p>

<h2>Ещё лучше: автоприглушение во время звонков</h2>

<p>SoundDial может автоматически понижать Spotify при присоединении к звонку. Включите автоприглушение в настройках, выберите, насколько снижать фоновый звук (по умолчанию 30%), и SoundDial сделает всё остальное. Ваша музыка приглушается при начале звонка и возвращается по его завершении. Никаких ручных настроек вообще.</p>

<p>Это рабочий процесс, который macOS должна поддерживать нативно: «Spotify на этом уровне, всё остальное на том уровне». Поскольку Apple его не создала, <a href="https://apps.apple.com/app/sounddial/id6772792641">SoundDial</a> заполняет этот пробел.</p>

<p>Разовая покупка в <a href="https://apps.apple.com/app/sounddial/id6772792641">Mac App Store</a>. Без подписки. macOS 14.2+.</p>
`,
